css:
/* by SelfMadeSystem */
/* The switch - the box around the slider */
.switch {
  --a: 0.5s ease-out;
  cursor: pointer;
  position: relative;
  display: inline-flex;
  height: 2em;
  border-radius: 2em;
  box-shadow: 0 0 0 0.66em #aaa;
  aspect-ratio: 212.4992/84.4688;
  background-color: #aaa;
}

/* Hide default HTML checkbox */
#check {
  opacity: 0;
  width: 0;
  height: 0;
}

.switch svg {
  height: 100%;
}

.switch svg path {
  color: #fffa;
  stroke-width: 16;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 0 46 87 999;
  transition: all var(--a);
  transform-origin: center;
}

#check:checked ~ .switch svg path {
  stroke-dasharray: 0 180 87 999;
  stroke-dashoffset: 1;
}
